mapper.select:
SELECT R. ID AS RECORDID, R.STAFF_NAME, R.CAUSE, R.START_TIME AS PATCHDATE, R.CREATE_TIME AS RECORDDATE, R.PROCESS_ID, S.COMP_NAME AS BUNAME FROM SMT_REPLACE_APPLICATION R LEFT JOIN SMT_STAFF S ON R.STAFF_BADGE = S.BADGE
R.STAFF_BADGE =#{query.staffBadge}
ORDER BY R.CREATE_TIME DESC

SELECT SP. ID AS PARK_ID, SS.COMP_NAME, SS.DEP_NAME, SRA.CAUSE, SRA.START_TIME, COUNT(*) as STATISTICS FROM SMT_REPLACE_APPLICATION SRA LEFT JOIN SMT_STAFF SS ON SRA.STAFF_BADGE = SS.BADGE LEFT JOIN SMT_PARK_BU SPB ON SS.COMP_ID = SPB.COMP_ID LEFT JOIN SMT_PARK SP ON SPB.PARK_ID = SP.ID
SP.ID = #{query.parkId}
AND SS.COMP_ID = #{query.compId}
AND SS.DEP_ID = #{query.depId}
AND SRA.START_TIME = #{query.startTime}
AND SP.ID IN
#{tempId}
GROUP BY SP.ID,SS.COMP_NAME,SS.DEP_NAME,SRA.CAUSE,SRA.START_TIME ORDER BY SRA.START_TIME DESC
